-- DRAWDOWN MISSION CREDITS: RECOVERY ONLY, PART 2 OF 2
-- Generated by tools/build-drawdown-credit-fallback.mjs from the frozen missions.json
-- (sha256 b9150c5b3075862fc66b989a12791278924414d2c6fc463fcb3dbbf67c6e6f66) and publication-policy.json.
-- Check with node tools/build-drawdown-credit-fallback.mjs --check. Applied SQL bytes never change.
--
-- RECOVERY ARTIFACT. Never a forward migration. Restore only after the publication is rolled back.
-- Apply this exact file with Supabase MCP apply_migration (it runs as postgres), then record its actual version.
-- Recovery requires separate authorization and verified permission before any later republication.
-- Both recovery parts are required to restore all 87 historical detail rows. They may run in either order.
-- Each part refuses unless all 125 Drawdown missions are drafts; no quotation is restored into a public mission.
-- The stored excerpts are historical recovery material, not permission evidence.
-- Exact before/after fingerprints reject concurrent or unexpected credit/source/license edits (55000); reruns do nothing.
-- No schema, grants, policies, original mission wording, proof hints, safety notes or assignments change.
-- Rollback files: 20261120050000_action_mission_drawdown_credit_fallback_01.rollback.sql, 20261120050000_action_mission_drawdown_credit_fallback_02.rollback.sql.
-- Proof: scripts/test/drawdown-credit-fallback.integration.mjs (isolated PostgreSQL), plus the root contract tests.
begin;
set local lock_timeout = '5s';
set local standard_conforming_strings = on;

do $drawdown_credit_fallback$
declare
  expected record;
  actual record;
  actual_md5 text;
  before_prefix text;
  after_prefix text;
begin
  -- Lock the existing catalog and missions in a stable order, including the 38 detail rows we preserve.
  perform d.mission_id from public.action_mission_details d
    join public.action_missions m on m.id = d.mission_id
    where d.catalog = 'drawdown' order by d.mission_id for update of d, m;
  if (select count(*) from public.action_mission_details d join public.action_missions m on m.id = d.mission_id
      where d.catalog = 'drawdown') <> 125 then
    raise exception 'Drawdown credit correction refused: expected all 125 imported missions and details' using errcode = '55000';
  end if;
  if exists (select 1 from public.action_mission_details d join public.action_missions m on m.id = d.mission_id
      where d.catalog = 'drawdown' and m.status <> 'draft') then
    raise exception 'Drawdown credit recovery refused: all 125 missions must be drafts' using errcode = '55000';
  end if;

  for expected in select * from (values
    ('7f666cb5-019d-5542-9809-9f8e606e13ab'::uuid, '7d69fdc195199abb6b2ab46e1a072a97', '44a58b7e3253d1db3a395c8399cd06ff', 'Photocatalytic methane-oxidizing coatings applied to roofs and other surfaces exposed to air can convert methane molecules that contact the surface into CO₂.'),
    ('7fd3053d-e1af-5477-a656-1a38e6569588'::uuid, '1195d3824479f197b39be7f9e3cf7dfb', '3b7db83076b8f1b8e9c0e96c8f7d1e4b', 'We define Improve Nonmotorized Transportation as increasing any form of travel that does not use a motor or engine. In theory, this includes a huge range of transportation modes, including horses, cross-country skis, sailboats, hand-operated rickshaws, and animal-drawn carriages. In practice, pedestrian travel and cycling account for most nonmotorized utilitarian passenger travel.'),
    ('82ce9fb9-9081-5523-a130-c37f3dc6900a'::uuid, '5c19e0e6aac98044cf392ffdf98c29b7', '064be13e7f5294ea2dccac828def75f1', 'Offshore wind turbines are ocean-based machines that harness natural wind to generate electricity. These turbines use the relatively strong winds over the water to rotate their blades, which power a generator to make electricity. The electricity travels through underwater cables to reach the land.'),
    ('8b493fa5-e6c6-5b83-8ac7-83741aa8882d'::uuid, '60f41b357c061c0a73ef752d6a877a43', 'e79486da512e42bbdfae938353418cd6', 'This solution avoids the burning of crop residues through the adoption of lower-emission options including straw balers, no-till seeders that can plant through residues, and developing markets for residue products. Some promising new techniques are also under development that could further increase future adoption and effectiveness of this solution.'),
    ('8d7a5b07-2074-56b3-8355-47f79877d568'::uuid, 'c59c44d9106c44e21922484220a33093', 'e387f3b367da1c8a0545c0c46a4e604e', 'We define Improve Windows & Glass as reducing the heat transferred through typical windows used in residential and nonresidential buildings by improving the thermal insulation capacity of the glass. Windows typically constitute a small portion of a building envelope but account for a substantial portion of the heat transferred (gained or lost) between the indoor space and the external environment.'),
    ('91846487-707c-509d-b421-488fcd896853'::uuid, 'e6fc518bae38e8e0a50adde14b6eca78', '510ae8e510c92ffb16f2079d83b1bb01', 'Biomass burial involves storing plant biomass, such as logs, woody debris, agricultural and forestry residues, and engineered bio-blocks, under conditions that prevent GHG-releasing decay – underground, above ground, or at ground level. Applications range from simple wood vaults buried underground to blocks of dried, compressed plant biomass sealed in impermeable barriers.'),
    ('93e0f0e8-0fe4-59f7-907f-05ac7287a250'::uuid, '327100f4cf0ebd897f9ce5907a6ad70a', '778edcc48e952f3da301c038256900fd', 'Alternative grazing refers to approaches to managing ruminant livestock – including multiple fenced paddocks and frequent animal movement, short grazing periods, and enforced rest periods for forage – that aim to increase soil organic carbon (SOC) by allowing vegetation to recover.'),
    ('940d2140-eb2f-58dc-b798-4ffc96fff671'::uuid, '00045f6705c0154a3d66aa1142a9e59a', 'd2308487a1344feaf1d4e830bb4203a8', 'Improve Steel Production involves replacing the use of fossil fuels in making steel from iron ore with electrolytic hydrogen and clean electricity.'),
    ('940ee6f3-0ff8-528c-bc73-30f4a3a03d29'::uuid, '31a38f50dc1e29fc3ef4c82cb27db7a0', '0a678c69776a204f4a0e027d3459b21c', 'A composting system diverts organic waste (OW) from landfills, reducing the production of methane and other GHG emissions. OW is defined as the combination of food waste and green waste, composed of yard and garden trimmings. Composting transforms it into a nutrient-rich soil supplement.'),
    ('960f0604-0a15-5012-aef8-a70418b535e3'::uuid, '4bc25f3b5e5aa90a5e681d2848d1f335', '4fec47c453e9caf41a10ddabe2be321b', 'Seaweed ecosystem protection is the long-term protection from degradation of wild subtidal brown and red seaweed ecosystems. Seaweeds, also called macroalgae, are photosynthetic marine organisms that absorb CO₂ from the water and convert it into biomass. This can lower surface-water CO₂ concentrations, allowing additional CO₂ from the atmosphere to be dissolved in the ocean.'),
    ('96685219-f741-5c38-97ad-cdc5eceba121'::uuid, 'eb48b2c8f367afe1588bf492fcac5e2f', 'e676aa124bc7de56ca4e7749514a4b6d', 'Restore Salt Marsh Ecosystems involves actively reestablishing salt marshes in areas where they were previously lost to conversion or other disturbance, allowing vegetation to regrow and carbon to accumulate in biomass and sediments. Advantages include salt marshes’ ability to durably store substantial quantities of carbon over long time periods and their numerous co-benefits for the environment and humans.'),
    ('9890ab86-5e07-5dfc-ab69-40874c388b01'::uuid, 'dd15bad30fd0074081b757e09472fd84', '8c4a5559404ae6f481b8575edc0155c0', 'Utility-scale solar PV refers to large solar power systems, typically installed on open land and connected directly to a central electric grid, that generate electricity for widespread distribution. These systems generally have an installed capacity above 1 MW. There are various configurations of utility-scale solar PV systems and we include fixed-tilt and tracking systems in this solution.'),
    ('9991a89f-e662-599f-84d2-e13c725e139d'::uuid, '745bc24036e3d9bdb61d30bea5e43028', '8009f7f9022ac0b8fbdbccdaefa51f9e', 'Deploying district cooling is the process of connecting multiple buildings in a dense area to a single, highly efficient source of cooling. The increased energy efficiency and reduction in use of high global warming potential refrigerants can translate into substantial emissions reductions and lower operating expenses (International Energy Agency [IEA], 2018; Energy Sector Management Assistance Program, 2020).'),
    ('9d1fdc5d-7617-5408-9269-8937cde77c7a'::uuid, 'a6884eed31fa69cc6e57bb24166dfc8b', 'b9d6d9ae72206d4eb8d42e32f520305b', 'Cool roofs cut GHG emissions from electricity generation by lowering the amount of cooling required to condition indoor spaces, thereby decreasing the use of air conditioners. Using cool roofs in building design lowers electricity use, improves thermal comfort for building occupants, and is relatively cheap to deploy.'),
    ('9f0aea98-532e-5160-8e48-eb1f76dcea68'::uuid, '62a0cd578e25f50ec97774c571be4d78', '7e6a83a92f9ccb410b5d7b2699b0c675', 'Deploy Ocean Electrochemistry uses electricity to separate seawater into acidic and basic solutions, which can be used to remove CO₂ in different ways. Acidic streams can be used to alter the chemistry of seawater, either by releasing dissolved CO₂ for capture and long-term storage or by weathering alkaline rocks and increasing seawater alkalinity.'),
    ('9f545890-788e-5ce4-b6ce-042251b8d441'::uuid, '1d6bf5b08ee5c81ed517abfa49340b28', '98e9a9966a6f3c34291914e1ee0df56e', 'Small modular nuclear reactors (SMRs) are advanced reactors designed to produce low-carbon electricity using smaller units that are factory-fabricated. SMRs aim to overcome the safety, cost, and scalability challenges of traditional large-scale nuclear power. They offer benefits such as passive safety systems, lower capital investment, and the potential to be deployed flexibly in remote or underserved regions.'),
    ('a4f79ed1-4534-57fc-a181-33e95fc87b0c'::uuid, '305204a777705b89fc192367a29913a8', '31c7a2e454d48c0de8ba8bbdd04bd57f', 'Seaweed (also called macroalgae) ecosystem restoration involves the reestablishment of wild red, brown, and green seaweed through interventions that recover degraded, damaged, or destroyed seaweed ecosystems. Healthy seaweed ecosystems remove CO₂ from the water column and convert it into biomass through photosynthesis, allowing additional CO₂ to be taken up in the ocean from the atmosphere.'),
    ('a6793da7-d182-5fa1-bf42-59bbc9796347'::uuid, '2af957fc8f0b8e89d2357cad6f41405b', '42bb89a7e431690040becc7c8c89c225', 'Decentralized composting systems involve waste generators in converting organic waste (OW) into a nutrient-rich soil supplement. They include a broad range of composting scales, from single households and community gardens to commercial and institutional operations (Platt, 2017).'),
    ('a67c7c74-c7f6-55fc-b546-3ea4b959745a'::uuid, 'dec9c48ed7f55b063a30e66023bd13c5', '3011a4582289b45a49ee5b6918252482', 'Irrigation water use efficiency involves reducing water use without compromising crop productivity by improving irrigation scheduling and/or equipment. Irrigation produces GHG emissions by altering biogeochemical cycling of carbon and nitrogen cycles in water and soils, and through energy use for pumping.'),
    ('a87e5275-c212-51bf-8650-22af893a7fd0'::uuid, '7e970ce3c0ae3945a00c45ed8c047c66', '4e9b828a4d1c78406cd0fc035eb6ab10', 'We define the Enhance Public Transit solution as increasing the use of any form of passenger transportation that uses publicly available vehicles (e.g., buses, streetcars, subways, commuter trains, and ferries) operating along fixed routes.'),
    ('b2a88b65-1e5b-5da4-9af7-011ca8f7874f'::uuid, '097369bdd392f1b49e13ff6a776f3b18', '95cd2fce59e4b349eaadf8edbe8ba7ed', 'This solution focuses on the legal protection of grassland and savanna ecosystems through the establishment of protected areas (PAs), which are managed with the primary goal of conserving nature, and land tenure for Indigenous peoples. These protections reduce grassland degradation, which preserves carbon stored in soils and vegetation and enables continued carbon sequestration by healthy grasslands.'),
    ('b5a1b342-9b1c-537e-920b-98226ad45669'::uuid, '1f138942cd4bbbfdc5547d50b2683473', 'f3f7ae8fe706f7be4f24f9ac3128e910', 'Protect Seafloors is the long-term protection of the seafloor from degradation, which helps preserve existing sediment carbon stocks and avoid CO₂ emissions. Advantages of seafloor protection include the conservation of biodiversity and marine ecosystems, potentially low costs, and the ability for immediate implementation.'),
    ('ba11cd9a-9260-548e-b5ef-93ff0f0445db'::uuid, '28a32774d0a78b48f22f465790fe188d', '56caa76726b06536df2fcc04e842e551', 'We define the Deploy LED Lighting solution as replacing energy-inefficient light sources with light-emitting diodes (LEDs).'),
    ('bcf5b9c7-0423-5586-8fba-06b57be0ff19'::uuid, 'd1532e8282e959c8cecaa12138331c54', 'f8c0a2d516f0aa3b529887c7da657f2a', 'Heat pumps use electricity to efficiently move heat from one place to another. This solution focuses on the replacement of fossil fuel–based heating systems with electric heat pumps.'),
    ('c44d0a0d-1c7f-5396-a071-80149e36c664'::uuid, 'c51189baaaac2cbc0628f1d158969698', 'c4f54b998e25969b32161ab7795cfd5a', 'This solution involves reducing the use of high-global warming potential (GWP) refrigerants, instead deploying lower-GWP refrigerants. High-GWP (>800 on a 100-yr basis) fluorinated gases (F-gases) are currently used as refrigerants in refrigeration, air conditioning, and heat pump systems. Over the lifetime of this equipment, refrigerants escape into the atmosphere where they contribute to climate change.'),
    ('cdc236e3-e4bd-5323-bcd4-ee9c4d77f135'::uuid, '509d56b350cce4d0dc4e6b97d3b77a12', 'ef1c383354af6e64b9c3d3c2291198af', 'Improving aquaculture involves reducing CO₂ and other GHG emissions during the production of farmed fish and other aquatic animals through better feed efficiency and the decarbonization of on-farm energy use. Advantages include reduced demand for feedstocks produced from both wild capture fisheries and terrestrial sources, which benefits marine and terrestrial ecosystems.'),
    ('da0a9a12-65d1-5a46-bcce-f359ebf13333'::uuid, '6b7e4dad78dd5157c831c36c003ea61c', 'a6c7abcc7816079afcb59a5513309a60', 'Replacing fossil-fuel-powered irrigation pumps with electric pumps powered by the grid can reduce emissions in most regions of the world. Electric irrigation pumps, which can also be powered by on-site clean energy, are more efficient than fossil fuel pumps. They are already cost-competitive and widely used, and adoption is increasing.'),
    ('dfb7d2eb-1373-59ae-bacd-22668b604f68'::uuid, '71a69a1f8a6822b20442d328bbe8d396', 'f3969f93375d6e6ca45198a60fef6b9e', 'Grassland and savanna restoration removes CO₂ from the atmosphere through photosynthesis as the ecosystem regrows, storing carbon in soils and vegetation. Grassland and savanna restoration faces relatively low barriers to implementation, provides substantial benefits for biodiversity, and may be deployable on large land areas.'),
    ('e2aa8ccd-9bc3-5941-8e81-3d3cd8cbb57c'::uuid, 'c43e7034aad50e06f5f8fdf77fdeb0d8', '266495af86e5e1d6e6b5e453faee0ead', 'The Mobilize Hybrid Cars solution entails shifting trips from fossil fuel–powered internal combustion engine (ICE) cars to more efficient, lower emitting hybrid cars. Hybrid cars include hybrid electric cars (HEVs) and plug-in hybrid electric cars (PHEVs). They are four-wheeled passenger cars that combine an ICE with an electric motor and battery to improve fuel efficiency and reduce emissions.'),
    ('e459b18c-7352-5f7c-b93c-d5cb383f850c'::uuid, '0c6d5c060fab365757448269815e8a66', '042be14e2174b27fc18ffeb31d244dbd', 'We define the Protect Forests solution as the long-term protection of tree-dominated ecosystems through establishment of protected areas (PAs), managed with the primary goal of conserving nature, and land tenure for Indigenous peoples. These protections reduce forest degradation, avoiding GHG emissions and ensuring continued carbon sequestration by healthy forests. This solution addresses protection of forests on mineral soils.'),
    ('e86c2226-e09f-59d4-90e6-3a8106cf4c2c'::uuid, '44572fd0b9b515c2c3cceb10556511c7', 'bc3a2246c5b64b68d1d3990fd5ac7cb5', 'We define improved diets as a reduction in ruminant meat consumption and a replacement with other protein-rich foods. Such a diet shift can be adopted incrementally through small behavioral changes that together lead to globally significant reductions in GHG emissions.'),
    ('ed9a7f1a-93f5-5ed7-852e-e99ed689ff36'::uuid, '4afea2413940977a4e1e02fa9bb96ebb', 'e1971fe460c824f85d36253d6a322e22', 'This solution reduces emissions by lowering the amount of food and its associated emissions that are lost or wasted across the supply chain, from production through consumption.'),
    ('f0533986-f7c6-53bd-82b4-c311e9875cb3'::uuid, 'c77889f1824e4392137f38e1eb853575', 'ed239d3395fb6016ca02951290ef1975', 'The Protect Peatlands solution is defined as legally protecting peatland ecosystems through establishment of protected areas (PAs), which preserves stored carbon and ensures continued carbon sequestration by reducing degradation of the natural hydrology, soils, and/or vegetation. This solution focuses on non-coastal peatlands that have not yet been drained or otherwise severely degraded.'),
    ('f364102d-e11f-583a-8249-e8ce07615a75'::uuid, '18dc3e66d2b28c5b2dd11c12668a63bf', '6ae49afdb786aa6666fd64434f148e86', 'Advanced geothermal energy is an emerging clean energy technology that harnesses the Earth’s subsurface heat to generate emissions-free baseload and dispatchable electricity and heat.'),
    ('f3e231f6-139d-504b-952e-b7deb39f9422'::uuid, 'f469aba86194ded7ccc5fae51fbb0ae2', '9a509344d438163d6afc8938b5b4ff80', 'Ruminant livestock, such as cattle, goats, and sheep, can be selectively bred for reduced enteric methane production.'),
    ('f7eeae72-b28f-5183-a392-f527edaf73ec'::uuid, '0361acf2b2410a70b925d6a2c4bb9802', '79ba1c513728ca78289bc0e62a7bf5fe', 'Low-flow fixtures reduce GHG emissions by reducing the volume of hot water used and therefore reducing the emissions from the energy used to heat that water (Kenway et al., 2023). Reduced water usage also leads to fewer emissions from treating and pumping water for domestic use (Yateh et al., 2024). Low-flow fixtures are low-cost and simple to install.'),
    ('f9085849-2b32-5436-8bbe-99e52ed4e57b'::uuid, '33d851bfbb219cf0b7d64ff917074f2d', '2cc31ca940a66334b2c34a9b21137995', 'Deploying leaf protein concentrates (LPCs) involves isolating high-quality proteins from green foliage, agricultural by-products, or aquatic flora for use in human food and animal feed.'),
    ('fabf57f7-bd14-5ec5-a980-41397329157a'::uuid, 'd45310ff0ce12ec9db310cc947ea016f', '463a083fe245bab4bc6c6228ab04b8bf', 'Improved manure management refers to the use of impermeable covers and physical or chemical treatments applied during the storage and processing of wet manure. These techniques can reduce methane emissions under anaerobic storage conditions and nitrous oxide emissions under aerobic conditions.'),
    ('febe45f0-f1d6-57ef-a5f4-73ed7e4985c4'::uuid, 'f59f4d666cccd5d6b10d8faca8c36f88', 'a0bde6bba58d34d10a6f2dd27574c556', 'Electric cars are four-wheeled passenger cars that run on electricity, usually from the electricity grid and stored in onboard batteries (i.e., not including fuel cell electric cars). This definition includes electric pickup trucks, motorhomes, and other such vehicles. It does not include two-wheeled vehicles or hybrid cars (which combine an electric motor with a gasoline or diesel engine).'),
    ('feec02fd-a269-5c00-94ac-c16737ad7546'::uuid, '057f1fea735c59a4e44b6a48bda70446', '2bbcae1eefc5e2246efeaaa7ac525fca', 'Cement is a key ingredient of concrete, a manufactured material used in massive quantities around the world. Cement production generates high CO₂ emissions from the production of clinker, a binding ingredient. These emissions come from not only the chemical reaction that produces clinker, but also burning fossil fuels to provide heat for this reaction.'),
    ('ff2a6de8-b97e-5642-acb6-25b39fcc4a9a'::uuid, '286e970be98284b1f40d24263f553083', '3d6aceae3798ff748237065099fc3217', 'In low- and middle-income countries, adopting cooking equipment that uses cleaner fuels or is more efficient has the potential to reduce GHG emissions from both cooking and deforestation due to unsustainable biomass use. Such equipment is readily available and inexpensive and provides significant social benefits. Barriers to adoption include cost and cultural practices, particularly in sub-Saharan Africa.'),
    ('ff5325cd-8f20-5ccf-9949-089b806a1d54'::uuid, '0eaae2d6bf7ad5afe197c1ab6cdb7fdc', '016eefb6e151dfab9ae53dea5ef0a312', 'Improve Building Envelopes cuts GHG emissions by enhancing the thermal resistance of the building shell, reducing unwanted heat exchange between the external environment and indoor spaces. These thermal improvements help decrease the amount of energy required to heat and cool buildings and the associated emissions.'),
    ('ffc85842-a7a4-5629-a9c1-8b41a58eb5c1'::uuid, 'a1ca4d32bf76353efd0f5173ea7084b2', '851dd4b50822de0f41d5d2baeed06f9f', 'Deploy Seaweed Farming for Food involves cultivating seaweed (often called macroalgae) in the ocean for human consumption as a partial replacement for low-protein foods grown on land (e.g., grains, vegetables). This solution considers the emissions avoided by substituting one kilogram of low-protein food with one kilogram of seaweed.')
  ) as v(id, before_md5, after_md5, original_about) order by id loop
    select d.* into actual from public.action_mission_details d
      where d.mission_id = expected.id and d.catalog = 'drawdown';
    if not found then
      raise exception 'Drawdown credit correction refused: missing target %', expected.id using errcode = '55000';
    end if;
    actual_md5 := md5(coalesce(actual.credit_line, '') || chr(31) || coalesce(actual.about, '') || chr(31) || coalesce(actual.about_credit, '') || chr(31) || coalesce(actual.source_url, '') || chr(31) || coalesce(actual.license_name, '') || chr(31) || coalesce(actual.license_url, '') || chr(31) || coalesce(actual.doi, ''));
    if actual_md5 = expected.before_md5 then continue; end if;
    if actual_md5 <> expected.after_md5 then
      raise exception 'Drawdown credit correction refused: credit or source changed for %', expected.id using errcode = '55000';
    end if;
    before_prefix := 'Solution summary from Project Drawdown (' || actual.source_url || '), used with permission';
    after_prefix := 'Solution listed in Project Drawdown''s Explorer (' || actual.source_url || ')';
    if left(actual.credit_line, length(after_prefix)) <> after_prefix then
      raise exception 'Drawdown credit correction refused: unexpected credit prefix for %', expected.id using errcode = '55000';
    end if;
    update public.action_mission_details
      set credit_line = before_prefix || substr(actual.credit_line, length(after_prefix) + 1),
          about = expected.original_about,
          about_credit = 'Solution summary © Project Drawdown, used with permission.',
          updated_at = now()
      where mission_id = expected.id;
    select md5(coalesce(d.credit_line, '') || chr(31) || coalesce(d.about, '') || chr(31) || coalesce(d.about_credit, '') || chr(31) || coalesce(d.source_url, '') || chr(31) || coalesce(d.license_name, '') || chr(31) || coalesce(d.license_url, '') || chr(31) || coalesce(d.doi, '')) into actual_md5 from public.action_mission_details d where d.mission_id = expected.id;
    if actual_md5 <> expected.before_md5 then
      raise exception 'Drawdown credit correction refused: resulting fingerprint differs for %', expected.id using errcode = '55000';
    end if;
  end loop;

end
$drawdown_credit_fallback$;

commit;
